python3 - <<'PY'
import openpyxl
wb=openpyxl.load_workbook('/root/output/result.xlsx', data_only=False)
ws=wb['Data']
# search for 2018..2022
years={2018,2019,2020,2021,2022,'2018','2019','2020','2021','2022'}
found=[]
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v=cell.value
        if v in years:
            found.append((cell.coordinate, v))

print('Found year-like cells:', len(found))
for item in found[:50]:
    print(item)
